{-# LANGUAGE DuplicateRecordFields #-}
{-# LANGUAGE RankNTypes #-}

-- | Engine for running EasySM contracts.
--
-- This module provides a Haskell harness that runs the MultiSig contract
-- using the code generated by agda2hs from the functional Agda definitions.
--
-- Actions fed to the contract are the augmented labels ('LabelPlus') generated
-- from @agda/EasySM/Examples/Functional/MultiSig.agda@ — no parallel action
-- type is defined here.
--
module Engine
  ( -- * Running the MultiSig contract
    runMultiSig
  , runMultiSigTraced
  , runMultiSigToJson
  , MultiSigResult(..)
    -- * Re-exported from the generated MultiSig module
  , LabelPlus(..)
  , Payment(..)
  , TraceEntry(..)
  ) where

import Numeric.Natural (Natural)

import EasySM.Functional.Augmented
  ( Conf(..), Valued(..), KeyHash, Value )
import EasySM.Functional.EasySM
  ( TimedConf(..), Trigger(..), MessageValidator(..), TraceEntry(..) )
import qualified EasySM.Functional.EasySM as EasySM
import EasySM.Examples.Functional.MultiSig
  ( State(..), LabelPlus(..), StatePlus(..), Payment(..)
  , multiSigDFA, multiSigAA, initialConf )
import Animation (traceToAnimationPlan, writeAnimationPlan, writeAutomatonConfig)


------------------------------------------------------------------------------
-- Running the MultiSig contract
--

-- | The result of running the MultiSig contract.
--
data MultiSigResult
  = MultiSigSuccess
      { finalState  :: State
      , finalValue  :: Value
      , finalTick   :: Natural
      , outputs     :: [Valued KeyHash]
      }
  | MultiSigFailure String

-- | A trivial message validator that accepts all messages.
--
acceptAllValidator :: MessageValidator State StatePlus ()
acceptAllValidator = MkMessageValidator (\_ _ _ -> True)

-- | Build a 'MultiSigResult' from the final timed configuration and outputs.
--
mkResult :: TimedConf State StatePlus -> [Valued KeyHash] -> MultiSigResult
mkResult finalTimed outs = MultiSigSuccess
  { finalState = baseState (conf finalTimed)
  , finalValue = value (conf finalTimed)
  , finalTick  = tick finalTimed
  , outputs    = outs
  }

-- | Run the MultiSig contract with an initial value and a list of actions.
--
-- Each action is an augmented label ('LabelPlus'), fed to the contract as a
-- 'StepT' trigger.
--
runMultiSig :: Value -> [LabelPlus] -> MultiSigResult
runMultiSig initialValue actions =
  let triggers  = map StepT actions
      initTimed = MkTimedConf (initialConf initialValue) 0
  in case EasySM.run multiSigDFA multiSigAA acceptAllValidator initTimed triggers of
       Nothing ->
         MultiSigFailure "Contract execution failed"
       Just (finalTimed, outputs) ->
         mkResult finalTimed outputs

-- | Run the MultiSig contract with tracing, returning the execution trace.
--
runMultiSigTraced :: Value -> [LabelPlus] -> Maybe ([TraceEntry State StatePlus LabelPlus () KeyHash], MultiSigResult)
runMultiSigTraced initialValue actions =
  let triggers  = map StepT actions
      initTimed = MkTimedConf (initialConf initialValue) 0
  in case EasySM.runTraced multiSigDFA multiSigAA acceptAllValidator initTimed triggers of
       Nothing ->
         Nothing
       Just (finalTimed, outputs, trace) ->
         Just (trace, mkResult finalTimed outputs)

-- | Run the MultiSig contract and write the trace to JSON files.
--
-- Writes two files:
-- * @planPath@ — the animation plan (trace of the execution)
-- * @configPath@ — the automaton configuration (hardcoded to MultiSig)
--
runMultiSigToJson :: Value -> [LabelPlus] -> FilePath -> FilePath -> IO (Maybe MultiSigResult)
runMultiSigToJson initialValue actions planPath configPath = do
  writeAutomatonConfig configPath
  let triggers  = map StepT actions
      initTimed = MkTimedConf (initialConf initialValue) 0
  case EasySM.runTraced multiSigDFA multiSigAA acceptAllValidator initTimed triggers of
    Nothing -> return Nothing
    Just (finalTimed, outputs, trace) -> do
      let plan = traceToAnimationPlan initialValue trace
      writeAnimationPlan planPath plan
      return (Just (mkResult finalTimed outputs))
